function campaignStage(index, name, treasureName, width, spawnY, layout) {
  const { goal, treasure, pieces, devices = [], sockets = [], hazards = [], signs = [], ...terrain } = layout;
  const zone = Math.floor(index / STAGES_PER_ZONE);
  return {
    index, name, treasureName, zone, width, mapY: 64, palette: zone ? 7 : 1,
    backdrop: STAGE_BACKDROPS[zone], song: SONG.zones[zone], spawn: point(32, spawnY),
    devices, hazards, signs, ...terrain,
    sockets: [...sockets, { id: 'exit', mode: 'exit', ...goal }],
    items: [
      { kind: 'treasure', index, ...treasure },
      ...pieces.map((p, i) => ({ kind: 'piece', index: index * 2 + i, ...p })),
    ],
  };
}

/** The campaign's stages, from the ROM (stages.py writes them: the long stages of the second pass did not fit in the code). */
function loadStages() {
  let text = '';
  for (const c of rom('stages')) text += String.fromCharCode(c);
  return JSON.parse(text).map(stage => campaignStage(...stage));
}
