function fx(n) {
  sfx(n, playing === SONG.practice ? 7 : SFX_CH[fxNext]);
  fxNext ^= 1;
}

function play(song) {
  if (playing === song) return;
  playing = song;
  music(song);
}

function scene(layer, asset, opts) {
  bg(layer, { mx: asset.mx, my: asset.my, mw: asset.w, mh: asset.h, ...opts });
}

// Terrain streams into a ring of 256 map columns (2,048 px, the width of Map RAM) as the camera moves, and BG1 wraps,
// so a stage can be wider than the map. Collisions use the stage's deck list, never the map.
const RING = 256, ROWS = SCREEN_H / 8;
let ringCol = new Int32Array(RING), decksAt = [];

function resetTerrain(level) {
  for (let row = 0; row < ROWS; row++) for (let col = 0; col < RING; col++) mset(col, level.mapY + row, 0);
  ringCol.fill(-1);
  decksAt = Array.from({ length: level.width / 8 }, () => []);
  for (const d of level.deck) for (let c = d.x / 8; c < (d.x + d.w) / 8; c++) decksAt[c].push(d);
}

/** The map entry for world column c, row `row`: each zone has its own tiles (art.py's terrain()); practice and the
 * lab use Foundry's in their own colours. */
function terrainTile(c, row) {
  const zone = course.practice || course.hub ? 0 : course.zone;
  for (const { x, y, w, h, oneWay } of decksAt[c]) {
    const dy = row * 8 - y;
    if (dy < 0 || dy >= h) continue;
    const i = c - x / 8, cols = w / 8, edge = i === 0 || i === cols - 1, my = course.mapY + row;
    const name = dy ? ((c * 7 + my * 3) % 5 ? 'Wall' : 'Wall2') : oneWay ? (edge ? 'LedgeEnd' : 'Ledge') : edge ? 'End' : 'Top';
    return tile(ART.tiles['deck' + name + zone], course.palette, !dy && i === cols - 1 && cols > 1);
  }
  return 0;
}

/** Write the columns the camera can see (and one each side) into their ring slots, if they are not there yet. */
function streamTerrain() {
  const first = Math.floor(camera / 8) - 1, last = Math.min(course.width / 8 - 1, first + SCREEN_W / 8 + 2);
  for (let c = Math.max(0, first); c <= last; c++) {
    const slot = c % RING;
    if (ringCol[slot] === c) continue;
    ringCol[slot] = c;
    for (let row = 0; row < ROWS; row++) mset(slot, course.mapY + row, terrainTile(c, row));
  }
}

function init() {
  if (dget(0) !== SAVE_VERSION) {
    for (let slot = 1; slot < 256; slot++) dset(slot, 0);
    dset(0, SAVE_VERSION);
  }
  selection = clamp(dget(STAGE_SLOT), 0, lastUnlocked());
  scene(0, ART.scenes.logo, { x: 0, y: -48, wrap: false });
  if (skipTitle) startCourse(FOUNDRY);
  else toTitle();
}

function writeSubPalette(index, colors) {
  colors.forEach((rgb, i) => {
    const value = parseInt(rgb, 16);
    color(index * 16 + i + 1, value >> 19, (value >> 11) & 31, (value >> 3) & 31);
  });
}

function setBackdrop(name) {
  scene(2, ART.scenes[name], { x: 0, y: 0, wrap: true, show: true });
}

function toTitle() {
  state = 'title';
  labMenu = null;
  paused = false;
  clock = 0;
  setBackdrop('factory');
  play(SONG.title);
}

function resetDevices(saved) {
  devices = course.devices.map((d, i) => saved?.devices[i] ? { ...saved.devices[i] } :
    { ...d, homeX: d.x, homeY: d.y, lastX: d.x, lastY: d.y, powered: false, direction: -1, wait: 0, phase: 0 });
  const byId = Object.fromEntries(devices.map(d => [d.id, d]));
  sockets = course.sockets.map((s, i) => {
    const socket = {
      ...s, active: saved?.switches[i] || false, platform: byId[s.mount],
      targets: (s.on || []).map(id => byId[id]),
      alternateTargets: (s.off || []).map(id => byId[id]),
    };
    routePower(socket);
    return socket;
  });
}

function startCourse(level, entry = level.spawn) {
  course = level;
  labMenu = null;
  if (!level.practice && !level.hub) {
    selection = level.index;
    dset(STAGE_SLOT, selection);
    if (level.zone) {
      writeSubPalette(6, SCENERY_COLORS[level.zone]);
      writeSubPalette(7, STAGE_DECK_COLORS[level.zone]);
    }
  }
  resetTerrain(level);
  checkpoint = null;
  reboots = 0;
  hazardTick = 0;
  resetDevices(null);
  spawnBit(entry);
  setBackdrop(course.backdrop);
  bg(1, { mx: 0, my: course.mapY, mw: RING, mh: ROWS, x: 0, y: 0, wrap: true });
  streamTerrain();
  state = level.hub ? 'lab' : 'play';
  paused = false;
  clock = 0;
  play(course.song);
}

function spawnBit({ x, y }) {
  bit = { x, y, vx: 0, vy: 0, support: course.deck.find(p => p.y === y && x >= p.x && x < p.x + p.w),
    coyote: COYOTE_FRAMES, jumpBuffer: 0, facingLeft: false, walk: 0,
    landUntil: 0, plugUntil: 0, pluggedSocket: null, cheerUntil: 0 };
  camera = clamp(x - SCREEN_W / 2, 0, course.width - SCREEN_W);
  deathTimer = 0;
}

const held = b => (input & (1 << b)) !== 0;
const pressed = b => held(b) && !(previousInput & (1 << b));

function update() {
  previousInput = input;
  input = 0;
  for (const b of BUTTONS) if (btn(b)) input |= 1 << b;
  if (paused) {
    updatePause();
    return;
  }
  clock++;
  if (state === 'title') {
    if (pressed(A) || pressed(START) || pressed(B)) {
      fx(SFX.confirm);
      startCourse(pressed(B) ? PRACTICE : LAB);
    }
    return;
  }
  if (state === 'clear') {
    if (pressed(B)) returnToLab(true);
    else if (pressed(LEFT) || pressed(A) || pressed(START)) {
      fx(SFX.confirm);
      if (pressed(LEFT) || course.practice) startCourse(course);
      else if (continuesZone()) startCourse(nextStage());
      else returnToLab(true);
    }
    return;
  }
  if (state === 'ending') {
    if (pressed(A) || pressed(START)) {
      if (clock < ENDING_READY_FRAME) clock = ENDING_READY_FRAME;
      else {
        dset(ENDING_SLOT, 1);
        startCourse(LAB);
      }
    }
    return;
  }
  if (state === 'lab' && labMenu) {
    updateLabMenu();
    return;
  }
  if (pressed(START)) {
    paused = true;
    pauseSel = 0;
    fx(SFX.pause);
    return;
  }
  if (state === 'lab') updateLab();
  else updateStage();
}

const pauseOptions = () => course.hub ? PAUSE_LAB : course.practice ? PAUSE_PRACTICE : PAUSE_STAGE;

function updatePause() {
  const direction = Number(pressed(DOWN)) - Number(pressed(UP));
  const count = pauseOptions().length;
  if (direction) {
    pauseSel = (pauseSel + direction + count) % count;
    fx(SFX.move);
  }
  if (pressed(B) || pressed(START)) {
    paused = false;
    fx(SFX.pause);
  } else if (pressed(A)) {
    fx(SFX.confirm);
    if (!pauseSel) paused = false;
    else if (course.hub) toTitle();
    else if (pauseSel === 1) startCourse(course);
    else returnToLab();
  }
}

function returnToLab(cleared = false) {
  if (cleared && nextStage()) selection = Math.min(nextStage().index, lastUnlocked());
  startCourse(LAB, course.practice ? point(534, 192) : LAB.spawn);
}

function updateLab() {
  moveBit();
  followBit();
  if (!pressed(B)) return;
  const socket = interaction();
  if (!socket) return;
  fx(SFX.plug);
  if (socket.id === 'practice') startCourse(PRACTICE);
  else if (socket.id === 'console' && readyToBoot()) {
    state = 'ending';
    clock = 0;
  } else {
    labMenu = socket.id;
    exhibit = 0;
  }
}

function updateLabMenu() {
  if (pressed(B) || pressed(START)) {
    labMenu = null;
    fx(SFX.confirm);
    return;
  }

  const horizontal = Number(pressed(RIGHT)) - Number(pressed(LEFT));
  const vertical = Number(pressed(DOWN)) - Number(pressed(UP));
  if (labMenu === 'console') {
    const next = clamp(selection + (vertical || horizontal), 0, lastUnlocked());
    if (next !== selection) {
      selection = next;
      fx(SFX.move);
    }
    if (pressed(A)) {
      fx(SFX.confirm);
      startCourse(CAMPAIGN[selection]);
    }
  } else {
    const columns = labMenu === 'treasures' ? 4 : 1;
    const count = labMenu === 'treasures' ? STAGE_COUNT : ZONES.length;
    const next = (exhibit + (vertical ? vertical * columns : horizontal) + count) % count;
    if (next !== exhibit) {
      exhibit = next;
      fx(SFX.move);
    }
  }
}

function advanceDevices() {
  for (const d of devices) {
    d.lastX = d.x;
    d.lastY = d.y;
    if (d.kind === 'scanline' && d.powered) {
      d.phase = (d.phase + 1) % SCANLINE_PERIOD;
    } else if (d.kind === 'shelf') {
      d.x += Math.sign((d.powered ? d.target : d.homeX) - d.x);
    } else if (d.kind === 'lift' && d.powered) {
      if (d.wait > 0) {
        d.wait--;
      } else {
        d.y += d.direction;
        if (d.y === d.top || d.y === d.homeY) {
          d.direction *= -1;
          d.wait = d.y === d.top ? 60 : 45;
        }
      }
    }
  }
}

function solidDevice(d) {
  if (d.kind === 'scanline') return d.powered && d.phase < SCANLINE_OFF;
  if (d.kind === 'bridge') return d.powered;
  return d.kind === 'lift' || d.kind === 'shelf';
}

function moveBit() {
  if (bit.support?.kind && !solidDevice(bit.support)) bit.support = null;
  const support = bit.support;
  const wasSupported = Boolean(support);
  const carryX = support?.kind === 'shelf' ? support.x - support.lastX : 0;
  if (support?.kind === 'lift') bit.y += support.y - support.lastY;
  if (pressed(A)) bit.jumpBuffer = BUFFER_FRAMES;
  const spring = wasSupported && devices.find(d => d.kind === 'spring' && d.powered && d.y === bit.y && overPlatform(d));
  if (spring || (bit.jumpBuffer > 0 && (wasSupported || bit.coyote > 0))) {
    bit.vy = spring ? -6.2 : JUMP_SPEED;
    bit.support = null;
    bit.coyote = 0;
    bit.jumpBuffer = 0;
    fx(spring ? SFX.spring : SFX.jump);
  } else {
    bit.vy = Math.min(FALL_LIMIT, bit.vy + (held(A) && bit.vy < 0 ? HELD_GRAVITY : GRAVITY));
  }

  const direction = Number(held(RIGHT)) - Number(held(LEFT));
  if (direction) {
    bit.vx = clamp(bit.vx + direction * (wasSupported ? GROUND_ACCEL : AIR_ACCEL), -RUN_SPEED, RUN_SPEED);
    bit.facingLeft = direction < 0;
  } else {
    const brake = wasSupported ? BRAKE : AIR_ACCEL;
    bit.vx -= Math.sign(bit.vx) * Math.min(Math.abs(bit.vx), brake);
  }
  const fallSpeed = bit.vy;
  moveHorizontally(carryX);
  moveVertically();
  if (!wasSupported && bit.support && fallSpeed > 2) bit.landUntil = clock + 6;

  if (bit.support) bit.coyote = COYOTE_FRAMES;
  else if (!wasSupported && bit.coyote > 0) bit.coyote--;
  if (bit.jumpBuffer > 0) bit.jumpBuffer--;
  bit.walk = bit.support && Math.abs(bit.vx) > 0.15 ? bit.walk + 1 : 0;
}

function moveHorizontally(carryX) {
  const dx = bit.vx + carryX;
  let x = clamp(bit.x + dx, BODY_HALF, course.width - BODY_HALF);
  for (const p of course.deck) {
    if (p.oneWay || bit.y <= p.y || bit.y - BODY_H >= p.y + p.h) continue;
    if (dx > 0 && bit.x + BODY_HALF <= p.x) x = Math.min(x, p.x - BODY_HALF);
    if (dx < 0 && bit.x - BODY_HALF >= p.x + p.w) x = Math.max(x, p.x + p.w + BODY_HALF);
  }
  if (x !== bit.x + dx) bit.vx = 0;
  bit.x = x;
}

function overPlatform(p) {
  return bit.x + BODY_HALF > p.x && bit.x - BODY_HALF < p.x + p.w;
}

function moveVertically() {
  let y = bit.y + bit.vy;
  let support = null;
  if (bit.vy >= 0) {
    for (const p of course.deck) {
      if (overPlatform(p) && bit.y <= p.y && y >= p.y) {
        y = p.y;
        support = p;
      }
    }
    for (const p of devices) {
      if (!solidDevice(p)) continue;
      // A rising lift can reach Bit from below between two frames.
      if ((!support || p.y < y) && overPlatform(p) && bit.y <= Math.max(p.y, p.lastY) && y >= p.y) {
        y = p.y;
        support = p;
      }
    }
  } else {
    for (const p of course.deck) {
      const underside = p.y + p.h + BODY_H;
      if (!p.oneWay && overPlatform(p) && bit.y >= underside && y < underside) y = underside;
    }
  }
  if (support || y !== bit.y + bit.vy) bit.vy = 0;
  bit.y = y;
  bit.support = support;
}

function followBit() {
  camera = clamp(camera, bit.x - 160, bit.x - 96);
  camera = clamp(camera, 0, course.width - SCREEN_W);
}

function socketPoint(s) {
  if (s.platform) return { x: s.platform.x + s.dx, y: s.platform.y + s.dy };
  return s;
}

// Find the segment's time interval inside one axis of a deck.
function axisInterval(from, to, low, high) {
  if (from === to) return from > low && from < high ? [-Infinity, Infinity] : [1, 0];
  const near = (low - from) / (to - from), far = (high - from) / (to - from);
  return [Math.min(near, far), Math.max(near, far)];
}

function clearSocketPath(x0, y0, x1, y1) {
  return !course.deck.some(p => {
    const [left, right] = axisInterval(x0, x1, p.x, p.x + p.w);
    const [top, bottom] = axisInterval(y0, y1, p.y, p.y + p.h);
    return Math.max(0, left, top) < Math.min(1, right, bottom);
  });
}

function interaction() {
  const centerY = bit.y - BODY_H / 2;
  let nearest = null, distance = Infinity;
  for (const s of sockets) {
    if (s.mode === 'once' && s.active) continue;
    const { x, y } = socketPoint(s);
    const dx = bit.x - x, dy = centerY - y;
    const dist = dx * dx + dy * dy;
    if (Math.abs(dx) <= SOCKET_X_REACH && Math.abs(dy) <= SOCKET_Y_REACH && dist < distance && clearSocketPath(bit.x, centerY, x, y)) {
      nearest = s;
      distance = dist;
    }
  }
  return nearest;
}

function routePower(s) {
  for (const d of s.targets) d.powered = s.active;
  for (const d of s.alternateTargets) d.powered = !s.active;
}

function plug(s) {
  if (s.mode === 'exit') {
    if (!course.practice) dset(CLEAR_SLOT, dget(CLEAR_SLOT) | (1 << course.index));
    state = 'clear';
    fx(SFX.clear);
    return;
  }
  s.active = !s.active;
  routePower(s);
  bit.pluggedSocket = s;
  bit.plugUntil = clock + PLUG_FRAMES;
  fx(SFX.plug);
  if (s.targets.length || s.alternateTargets.length) fx(SFX.power);
}

const stageCleared = (index = 0) => (dget(CLEAR_SLOT) & (1 << index)) !== 0;

function lastUnlocked() {
  const firstIncomplete = CAMPAIGN.findIndex(stage => !stageCleared(stage.index));
  return firstIncomplete < 0 ? CAMPAIGN.length - 1 : firstIncomplete;
}

const nextStage = () => course.practice || course.hub ? null : CAMPAIGN[course.index + 1];
const continuesZone = () => nextStage() && nextStage().zone === course.zone;
const stageNumber = stage => (stage.zone + 1) + '-' + (stage.index % STAGES_PER_ZONE + 1);
const itemSlot = item => item.kind === 'treasure' ? TREASURE_SLOT : PIECE_SLOT;
const hasItem = item => (dget(itemSlot(item)) & (1 << item.index)) !== 0;
const collected = (kind, level = course) => level.items.filter(item => item.kind === kind && hasItem(item)).length;
const tally = (mask, count) => {
  let total = 0;
  for (let i = 0; i < count; i++) total += (mask >> i) & 1;
  return total;
};
const puzzleMask = zone => (dget(PIECE_SLOT) >>> (zone * PUZZLE_PARTS)) & FULL_PUZZLE;
const hasTreasure = () => course.items.some(item => item.kind === 'treasure' && hasItem(item));

function hazardState(h) {
  if (h.kind === 'contact') {
    const phase = (hazardTick + h.offset) % CONTACT_PERIOD;
    return {
      y: h.y - 9, height: 9, phase,
      warning: phase >= CONTACT_WARNING && phase < CONTACT_LIVE,
      danger: phase >= CONTACT_LIVE,
    };
  }

  const phase = (hazardTick + h.offset) % PRESS_PERIOD;
  const elapsed = phase - (PRESS_IDLE + PRESS_WARNING);
  const depth = elapsed < PRESS_DROP ? clamp(elapsed / PRESS_DROP, 0, 1) :
    clamp(1 - (elapsed - PRESS_DROP - PRESS_HOLD) / PRESS_RETURN, 0, 1);
  return {
    y: Math.floor(lerp(h.raisedY, h.y - 12, depth)), height: 12, phase,
    warning: phase >= PRESS_IDLE && elapsed < 0, danger: elapsed >= 0,
  };
}

function dangerAtBit(h) {
  if (!overPlatform(h)) return false;
  const { y, height, danger } = hazardState(h);
  return danger && bit.y > y && bit.y - BODY_H < y + height;
}

function updateStage() {
  if (deathTimer > 0) {
    if (--deathTimer === 0) {
      resetDevices(checkpoint);
      hazardTick = checkpoint?.hazardTick ?? 0;
      spawnBit(checkpoint?.beacon || course.spawn);
      fx(SFX.reboot);
    }
    return;
  }

  hazardTick++;
  advanceDevices();
  moveBit();
  followBit();

  if (bit.y - BODY_H >= SCREEN_H + 8 || course.hazards.some(dangerAtBit)) {
    deathTimer = RESPAWN_FRAMES;
    reboots++;
    fx(SFX.fall);
    return;
  }
  const index = bit.support ? course.beacons.findIndex((b, i) => i > (checkpoint?.index ?? -1) &&
    bit.y === b.y && Math.abs(bit.x - b.x) < 12) : -1;
  if (index >= 0) {
    const beacon = course.beacons[index];
    // A one-shot socket comes back unplugged with its devices as the stage began, so it can be used again: a
    // shelf or lift saved mid-move could otherwise strand Bit for good (plug in, then back onto this beacon).
    const oneShot = new Set(sockets.filter(s => s.mode === 'once').flatMap(s => [...s.targets, s.platform]));
    checkpoint = { index, beacon, hazardTick, devices: devices.map(d => oneShot.has(d) ? null : { ...d }),
      switches: sockets.map(s => s.mode !== 'once' && s.active) };
    fx(SFX.checkpoint);
  }
  for (const item of course.items) {
    if (hasItem(item) || Math.abs(bit.x - item.x) >= 14 || Math.abs(bit.y - BODY_H / 2 - item.y) >= 15) continue;
    const slot = itemSlot(item);
    dset(slot, dget(slot) | (1 << item.index));
    bit.cheerUntil = clock + 18;
    fx(item.kind === 'treasure' ? SFX.treasure : SFX.piece);
  }
  if (pressed(B)) {
    const socket = interaction();
    if (socket) plug(socket);
  }
}

function draw() {
  cls();
  const title = state === 'title';
  bg(0, { show: title });
  bg(1, { show: !title });
  if (!title) streamTerrain();
  const scroll = title ? Math.floor(clock / 4) : Math.floor(camera);
  bgscroll(2, Math.floor(scroll / 3), 0);
  if (title) drawTitle();
  else {
    bgscroll(1, scroll, 0);
    if (course.hub) drawLab(scroll);
    else drawStage(scroll);
    if (paused) drawPause();
    else if (state === 'clear') drawClear();
    else if (state === 'ending') drawEnding();
    else if (labMenu) drawLabMenu();
  }
}

function drawTitle() {
  const cleared = tally(dget(CLEAR_SLOT), CAMPAIGN.length);
  centered(cleared ? 'STAGES CLEARED  ' + cleared + '/' + STAGE_COUNT : 'A NOVA-16 ADVENTURE', 116, C.MUTED);
  panel(26, 145, 204, 51);
  centered('A  ENTER LAB', 155, C.WHITE);
  centered('B  PRACTICE', 175, C.CYAN);
}

const LAB_LABELS = ['NOVA-16', 'TREASURES', 'PUZZLE WALL', 'PRACTICE'];
const PUZZLE_NAMES = ['CONTROLLER CUTAWAY', 'CARTRIDGE CUTAWAY', 'CIRCUIT CUTAWAY', 'CRT CUTAWAY'];
const treasureSprite = index => ART.sprites['displayTreasure' + index];
const puzzleSprite = zone => ART.sprites['puzzleArt' + zone];

function cabinet(x, y, w, h) {
  rectfill(x + 3, y + 3, w, h, C.INK);
  rectfill(x, y, w, h, C.DARK);
  rect(x, y, w, h, C.TRIM);
  line(x + 2, y + 2, x + w - 3, y + 2, C.PURPLE);
}

function labLabel(text, center, y) {
  const x = center - text.length * 4;
  rectfill(x - 5, y - 3, text.length * 8 + 10, 14, C.PANEL);
  print(text, x, y, C.WHITE);
}

function drawLab(scroll) {
  const [consoleStation, treasures, puzzles, practice] = sockets.map(s => s.x - scroll);
  const focus = state === 'lab' && !labMenu ? interaction() : null;
  clip(0, 16, SCREEN_W, SCREEN_H - 16);

  cabinet(consoleStation - 44, 81, 88, 51);
  labLabel(LAB_LABELS[0], consoleStation, 91);
  for (let i = 0; i < STAGE_COUNT; i++) {
    rectfill(consoleStation - 35 + 6 * i, 113, 4, 4, stageCleared(i) ? C.CYAN : C.TRIM);
  }
  cabinet(consoleStation - 36, 149, 72, 8);
  drawSprite(ART.sprites.labConsole, consoleStation - 16, 123, false, 2);

  cabinet(treasures - 56, 73, 112, 86);
  labLabel(LAB_LABELS[1], treasures, 82);
  for (let i = 0; i < STAGE_COUNT; i++) {
    const x = treasures - 53 + (i % 6) * 18, y = 102 + Math.floor(i / 6) * 22;
    rectfill(x, y, 18, 18, C.PANEL);
    rect(x, y, 18, 18, C.TRIM);
    if (collected('treasure', CAMPAIGN[i])) drawArtifact(treasureSprite(i), x + 1, y + 1);
  }

  cabinet(puzzles - 61, 80, 122, 79);
  labLabel(LAB_LABELS[2], puzzles, 90);
  for (let zone = 0; zone < ZONES.length; zone++) {
    const x = puzzles - 51 + 26 * zone;
    const mask = puzzleMask(zone);
    rectfill(x, 112, 22, 22, C.PANEL);
    rect(x, 112, 22, 22, mask === FULL_PUZZLE ? C.CYAN : C.TRIM);
    for (let i = 0; i < PUZZLE_PARTS; i++) {
      rectfill(x + 3 + (i % 3) * 6, 117 + Math.floor(i / 3) * 7, 4, 5, (mask & (1 << i)) ? C.CYAN : C.DARK);
    }
    print(String(tally(mask, PUZZLE_PARTS)), x + 7, 139, C.MUTED);
  }

  cabinet(practice - 42, 98, 84, 94);
  rectfill(practice - 28, 117, 56, 75, C.INK);
  rect(practice - 28, 117, 56, 74, C.PURPLE);
  rectfill(practice - 27, 118, 3, 71, C.TRIM);
  rectfill(practice + 25, 118, 2, 71, C.CYAN);
  for (let i = 0; i < 3; i++) {
    line(practice - 13 + i * 8, 140, practice - 9 + i * 8, 144, C.CYAN);
    line(practice - 9 + i * 8, 144, practice - 13 + i * 8, 148, C.CYAN);
  }
  labLabel(LAB_LABELS[3], practice, 109);

  for (const s of sockets) {
    const boot = s.id === 'console' && readyToBoot();
    const label = s.id === 'console' ? (boot ? 'B BOOT' : 'B STAGES') :
      s.id === 'practice' ? 'B ENTER' : 'B VIEW';
    const prompt = focus === s ? label : '';
    drawSocket(s.x - scroll, s.y, boot ? ART.sprites.socketLive : ART.sprites.socketIdle, prompt);
  }
  drawSprite(bitSprite(), Math.floor(bit.x) - scroll - 16, Math.floor(bit.y) - 31, bit.facingLeft);
  clip();
  rectfill(0, 0, SCREEN_W, 16, C.PANEL);
  line(0, 15, SCREEN_W - 1, 15, C.TRIM);
  print('BIT\'S LAB', 5, 4, C.WHITE);
  print('T ' + tally(dget(TREASURE_SLOT), STAGE_COUNT) + '/' + STAGE_COUNT + ' P ' + tally(dget(PIECE_SLOT), PIECE_COUNT) + '/' + PIECE_COUNT, 133, 4, C.CYAN);
}

// The exhibits use the same tile art in the room and inside solid overlay panels. The overlay covers sprites, so
// they are drawn on it: as runs of one colour (within one part of a puzzle), worked out once for each picture. A
// picture's parts: three columns (11, 11 and 10 px of 32) by two rows, numbered along the top row first.
const partCol = (col, size) => col < Math.ceil(size / 3) ? 0 : col < 2 * Math.ceil(size / 3) ? 1 : 2;
const artifactRuns = new Map();
function runsOf(asset) {
  let runs = artifactRuns.get(asset);
  if (runs) return runs;
  runs = [];
  const sx = (asset.tile & 15) * 8, sy = (asset.tile >> 4) * 8, size = asset.size;
  for (let row = 0; row < size; row++) {
    for (let col = 0; col < size;) {
      const pixel = sget(sx + col, sy + row), part = (row >= size / 2 ? 3 : 0) + partCol(col, size);
      let len = 1;
      while (col + len < size && partCol(col + len, size) === partCol(col, size) && sget(sx + col + len, sy + row) === pixel) len++;
      if (pixel) runs.push({ row, col, len, pixel, part });
      col += len;
    }
  }
  artifactRuns.set(asset, runs);
  return runs;
}

function drawArtifact(asset, x, y, scale = 1, parts = FULL_PUZZLE) {
  if (!parts || x >= SCREEN_W || y >= SCREEN_H || x + asset.size * scale <= 0 || y + asset.size * scale <= 0) return;
  const palette = 128 + asset.pal * 16;
  for (const { row, col, len, pixel, part } of runsOf(asset)) {
    if (parts & (1 << part)) rectfill(x + col * scale, y + row * scale, len * scale, scale, palette + pixel);
  }
}

function drawLabMenu() {
  if (labMenu === 'console') drawStageSelect();
  else if (labMenu === 'treasures') drawTreasureCase();
  else drawPuzzleWall();
}

function drawStageSelect() {
  panel(8, 17, 240, 192);
  print('STAGE SELECT', 20, 26, C.WHITE);
  print('T  P', 194, 26, C.CYAN);
  const unlocked = lastUnlocked();
  for (const stage of CAMPAIGN) {
    const y = 40 + stage.index * 12, selected = stage.index === selection;
    const canPlay = stage.index <= unlocked;
    if (selected) rectfill(13, y - 2, 230, 11, C.TRIM);
    if (selected) print('>', 18, y, C.CYAN);
    print(stageNumber(stage), 29, y, canPlay ? C.MUTED : C.PURPLE);
    print(stage.name, 58, y, canPlay ? C.WHITE : C.PURPLE);
    if (canPlay) {
      print(String(collected('treasure', stage)), 201, y, C.GOLD);
      print(String(collected('piece', stage)), 224, y, C.CYAN);
    } else print('-', 224, y, C.MUTED);
  }
  centered('A PLAY    B BACK', 190, C.WHITE);
}

function drawTreasureCase() {
  panel(9, 18, 238, 187);
  centered('TREASURE CASE  ' + tally(dget(TREASURE_SLOT), STAGE_COUNT) + '/' + STAGE_COUNT, 27, C.GOLD);
  for (const stage of CAMPAIGN) {
    const i = stage.index, x = 24 + (i % 4) * 53, y = 41 + (i >> 2) * 34;
    const found = collected('treasure', stage);
    rectfill(x, y, 49, 31, C.INK);
    rect(x, y, 49, 31, exhibit === i ? C.GOLD : C.TRIM);
    if (found) drawArtifact(treasureSprite(i), x + 16, y + 2);
    else print('?', x + 21, y + 6, C.MUTED);
    print(stageNumber(stage), x + 13, y + 21, C.MUTED);
  }
  const selected = CAMPAIGN[exhibit];
  centered(collected('treasure', selected) ? selected.treasureName : 'UNFOUND TREASURE', 147, C.WHITE);
  centered(selected.name, 161, C.MUTED);
  centered('D-PAD SELECT   B BACK', 184, C.CYAN);
}

function drawPuzzleWall() {
  panel(10, 16, 236, 191);
  centered('PUZZLE WALL', 25, C.WHITE);
  for (let zone = 0; zone < ZONES.length; zone++) {
    const y = 49 + zone * 24, selected = exhibit === zone;
    if (selected) rectfill(17, y - 4, 116, 19, C.TRIM);
    print(ZONES[zone], 22, y, selected ? C.WHITE : C.MUTED);
    print(tally(puzzleMask(zone), PUZZLE_PARTS) + '/' + PUZZLE_PARTS, 103, y, C.CYAN);
  }
  const mask = puzzleMask(exhibit), x = 155, y = 48, cols = [0, 22, 44, 64];
  for (let i = 0; i < PUZZLE_PARTS; i++) {
    const left = x + cols[i % 3], w = cols[i % 3 + 1] - cols[i % 3], top = y + Math.floor(i / 3) * 32;
    rectfill(left, top, w, 32, C.INK);
    rect(left, top, w, 32, C.TRIM);
    if (!(mask & (1 << i))) print('?', left + w / 2 - 4, top + 12, C.MUTED);
  }
  drawArtifact(puzzleSprite(exhibit), x, y, 2, mask);
  rect(x - 2, y - 2, 68, 68, mask === FULL_PUZZLE ? C.CYAN : C.TRIM);
  centered(mask === FULL_PUZZLE ? PUZZLE_NAMES[exhibit] : tally(mask, PUZZLE_PARTS) + '/' + PUZZLE_PARTS + ' PUZZLE PIECES', 149, C.WHITE);
  centered('D-PAD SELECT   B BACK', 179, C.CYAN);
}

function drawEnding() {
  panel(13, 24, 230, 177);
  const ready = clock >= ENDING_READY_FRAME;
  const dots = Math.min(8, Math.floor(clock / 10));
  centered(ready ? 'NOVA-16 ONLINE' : 'BOOTING NOVA-16', 39, C.CYAN);
  drawArtifact(ART.sprites.labConsole, 96, 56, 2);
  for (let i = 0; i < 8; i++) rectfill(73 + 14 * i, 116, 9, 4, i < dots ? C.CYAN : C.TRIM);
  if (ready) {
    centered('ALL FOUR WORLDS RESTORED', 135, C.WHITE);
    centered(tally(dget(TREASURE_SLOT), STAGE_COUNT) + '/' + STAGE_COUNT + ' TREASURES', 149, C.MUTED);
    centered(tally(dget(PIECE_SLOT), PIECE_COUNT) + '/' + PIECE_COUNT + ' PIECES', 160, C.MUTED);
    centered('A BACK TO LAB', 176, C.GOLD);
  } else centered(clock < 45 ? 'CHECKING CARTRIDGE' : 'RECONNECTING CONTROLLERS', 146, C.WHITE);
}

function drawDevices(scroll) {
  for (const d of devices) {
    const x = d.x - scroll;
    const warning = d.kind === 'scanline' && d.powered && d.phase >= SCANLINE_WARNING && d.phase < SCANLINE_OFF;
    const accent = warning ? C.GOLD : d.powered ? C.CYAN : course.practice ? C.PURPLE : C.CORAL;
    if (d.kind === 'lift') {
      for (const rail of [x + 3, x + d.w - 5]) rectfill(rail, d.top, 2, d.homeY - d.top + 8, C.TRIM);
    }
    if ((d.kind === 'bridge' || d.kind === 'scanline') && !solidDevice(d)) {
      for (let n = 4; n < d.w; n += 12) rectfill(x + n, d.y + 2, 4, 2, d.powered ? C.STEEL : C.TRIM);
      continue;
    }
    const y = d.kind === 'spring' ? d.y - 3 : d.y;
    const h = d.kind === 'spring' ? 3 : 8;
    rectfill(x, y, d.w, h, C.INK);
    rectfill(x + 1, y, d.w - 2, 2, accent);
    if (h > 3) rectfill(x + 3, y + 4, d.w - 6, 2, C.STEEL);
    if (d.kind === 'scanline') {
      const blink = warning && d.phase % 8 < 4;
      for (let n = 5; n < d.w; n += 9) {
        rectfill(x + n, y + 4, blink ? 2 : 4, 2, warning ? C.CORAL : C.SIGNAL);
      }
    }
  }
}

function drawHazards(scroll) {
  for (const h of course.hazards) {
    const x = h.x - scroll;
    if (x + h.w <= 0 || x >= SCREEN_W) continue;
    const { y, height, phase, warning, danger } = hazardState(h);
    const flash = phase % 8 < 4;
    const signal = danger ? C.HOT : warning ? C.GOLD : C.PURPLE;
    if (h.kind === 'contact') {
      rectfill(x, h.y - 2, h.w, 4, C.INK);
      for (let i = 2; i < h.w - 1; i += 5) {
        rectfill(x + i, h.y - 2, 3, 2, signal);
        if (danger || warning && flash) {
          const tip = h.y - (danger ? 7 + ((i + phase) % 3) : 5);
          line(x + i, h.y - 2, x + i + 2, tip, signal);
          if (danger) line(x + i + 2, tip, x + i + 4, h.y - 5, C.GOLD);
        }
      }
    } else {
      rectfill(x + 13, h.raisedY - 14, 14, y - h.raisedY + 16, C.INK);
      rectfill(x + 16, h.raisedY - 14, 4, y - h.raisedY + 16, C.STEEL);
      rectfill(x, y, h.w, height, C.INK);
      rectfill(x + 2, y + height - 3, h.w - 4, 2, signal);
      for (let i = 5; i < h.w - 3; i += 8) line(x + i, y + 2, x + i - 2, y + 6, C.STEEL);
      if (warning) {
        rect(x - 1, y - 1, h.w + 2, height + 2, flash ? C.GOLD : C.CORAL);
        const marker = x + Math.floor(h.w / 2);
        const arrowY = h.y - (flash ? 8 : 12);
        line(marker - 4, arrowY, marker, arrowY + 4, C.GOLD);
        line(marker, arrowY + 4, marker + 4, arrowY, C.GOLD);
      }
    }
  }
}

function drawStage(scroll) {
  const prompt = interaction();
  let queueTerminal = null;
  clip(0, 16, SCREEN_W, SCREEN_H - 16);
  drawDevices(scroll);
  drawHazards(scroll);
  for (const s of sockets) {
    const { x, y } = socketPoint(s);
    // the exit's terminal stands behind its socket (drawn after it, so the socket stays in front)
    if (s.mode === 'exit') queueTerminal = { x: x - scroll - 16, y: y - 21 };
    const live = s.active || s.mode === 'exit';
    const label = s.mode === 'exit' ? 'B EXIT' : s.targets.some(d => d.kind === 'scanline') ? 'B POWER' : s.mode === 'switch' && live ? 'B RESET' : 'B PLUG';
    drawSocket(x - scroll, y, live ? ART.sprites.socketLive : ART.sprites.socketIdle, prompt === s ? label : '');
  }
  if (queueTerminal) drawSprite(ART.sprites.exitTerminal, queueTerminal.x, queueTerminal.y, false, 2);
  if (clock < bit.plugUntil) {
    const { x, y } = socketPoint(bit.pluggedSocket);
    drawPlugSparks(x - scroll, y);
  }
  for (const sign of course.signs) {
    const w = sign.text.length * 8 + 12, x = sign.x - scroll - w / 2;
    rectfill(x, sign.y, w, 14, C.PANEL);
    rect(x, sign.y, w, 14, C.TRIM);
    print(sign.text, x + 6, sign.y + 4, C.MUTED);
  }
  for (const [i, beacon] of course.beacons.entries()) {
    const x = beacon.x - scroll, lit = i <= (checkpoint?.index ?? -1);
    rectfill(x - 1, beacon.y - 28, 3, 28, C.TRIM);
    rectfill(x + 2, beacon.y - 27, 11, 7, lit ? C.CYAN : C.PURPLE);
    rectfill(x + 2, beacon.y - 22, 11, 2, lit ? C.STEEL : C.TRIM);
  }
  if (course.practice) drawSprite(ART.sprites.labConsole, 42 - scroll, 150, false, 2);
  for (const item of course.items) {
    if (hasItem(item)) continue;
    const bob = Math.floor(clock / 12) % 4;
    const asset = ART.sprites[item.kind === 'treasure' ? 'treasure' : 'piece'];
    drawSprite(asset, item.x - scroll - 8, item.y - 8 + (bob === 3 ? 1 : bob));
  }
  if (!deathTimer) drawSprite(bitSprite(), Math.floor(bit.x) - scroll - 16, Math.floor(bit.y) - 31, bit.facingLeft);
  clip();
  rectfill(0, 0, SCREEN_W, 15, C.PANEL);
  rectfill(0, 15, SCREEN_W, 1, C.TRIM);
  if (course.practice) {
    print('LAB PRACTICE', 5, 4, C.WHITE);
    print('STATION ' + ((checkpoint?.index ?? -1) + 2) + '/3', 154, 4, C.CYAN);
  } else {
    print(stageNumber(course) + ' ' + ZONES[course.zone], 5, 4, C.WHITE);
    print('T ' + collected('treasure') + '/1   P ' + collected('piece') + '/2', 131, 4, C.GOLD);
  }
  if (deathTimer && !paused) centered('REBOOTING', 70, C.MUTED);
  else if (!course.practice && state === 'play' && clock < 100) {
    const width = course.name.length * 8 + 12;
    rectfill((SCREEN_W - width) / 2, 21, width, 14, C.PANEL);
    rect((SCREEN_W - width) / 2, 21, width, 14, C.TRIM);
    centered(course.name, 25, C.WHITE);
  }
}

function bitSprite() {
  const sprites = ART.sprites;
  if (state === 'clear' || clock < bit.cheerUntil) return sprites.heroCheer;
  if (clock < bit.plugUntil) return sprites.heroPlug;
  if (!bit.support) return bit.vy < 0 ? sprites.heroJump : sprites.heroFall;
  if (clock < bit.landUntil) return sprites.heroLand;
  if (bit.walk) return WALK[Math.floor(bit.walk / 5) % WALK.length];
  return clock % 150 >= 145 ? sprites.heroBlink : sprites.heroIdle;
}

function drawPlugSparks(x, y) {
  const spread = Math.floor((PLUG_FRAMES + clock - bit.plugUntil) / 3);
  line(x - 9 - spread, y - 8, x - 12 - spread, y - 11, C.CYAN);
  line(x + 13 + spread, y - 5, x + 16 + spread, y - 7, C.CYAN);
  rectfill(x + 9, y - 13 - spread, 1, 2, C.GOLD);
}

function drawSocket(x, y, asset, prompt) {
  drawSprite(asset, x - 8, y - 8, false, 2);
  if (!prompt || paused || deathTimer || (state !== 'play' && (state !== 'lab' || labMenu))) return;
  const width = prompt.length * 8;
  const left = clamp(x - width / 2, 3, SCREEN_W - width - 3);
  rectfill(left - 2, y - 32, width + 4, 13, C.INK);
  rect(left - 2, y - 32, width + 4, 13, C.TRIM);
  print(prompt, left, y - 30, C.WHITE);
}

function drawSprite(asset, x, y, flip = false, prio = 3) {
  if (x <= -asset.size || x >= SCREEN_W || y <= -asset.size || y >= SCREEN_H) return;
  spr(asset.tile, x, y, { size: asset.size, pal: asset.pal, prio, fx: flip });
}

function drawPause() {
  const items = pauseOptions();
  panel(39, 70, 178, 41 + items.length * 14);
  centered('PAUSED', 80, C.GOLD);
  for (let i = 0; i < items.length; i++) {
    print(i === pauseSel ? '>' : ' ', 48, 99 + i * 14, C.CYAN);
    print(items[i], 64, 99 + i * 14, i === pauseSel ? C.WHITE : C.MUTED);
  }
}

function drawClear() {
  const next = nextStage();
  panel(24, 60, 208, 102);
  const title = course.practice ? 'PRACTICE COMPLETE' : next ? 'STAGE CLEAR' : 'CAMPAIGN CLEAR';
  centered(title, 71, C.GOLD);
  if (course.practice) centered('ALL 3 STATIONS', 97, C.MUTED);
  else {
    centered(hasTreasure() ? course.treasureName : 'TREASURE MISSING', 90, C.MUTED);
    centered('PIECES ' + collected('piece') + '/2', 105, C.MUTED);
  }
  centered(course.practice ? 'A REPLAY   B LAB' : continuesZone() ? 'A NEXT   B LAB' : 'A BACK TO LAB', 126, C.WHITE);
  if (!course.practice) centered('LEFT REPLAYS STAGE', 143, C.MUTED);
}

function panel(x, y, w, h) {
  rectfill(x + 3, y + 3, w, h, C.INK);
  rectfill(x, y, w, h, C.PANEL);
  rect(x, y, w, h, C.TRIM);
}

function centered(text, y, colorIndex) {
  print(text, 128 - text.length * 4, y, colorIndex);
}

function scanline(y) {
  const name = state === 'title' ? 'sky' : (course.practice || course.hub) ? 'labSky' :
    STAGE_SKIES[course.zone];
  gradientLine(ART.gradients[name], y);
}
